        $$('.mT', el).forEach((x) => { x.onchange = () => { read(); paint(); }; });
        $$('.addM', el).forEach((b) => { b.onclick = () => { read(); custom[+b.dataset.pi].metrics.push({ k: '', label: '', unit: '', t: 'oid', oid: '', agg: 'avg', scale: 1, dtype: 'number', on: true }); paint(); }; });
