          const dl = dialog('Pick readings from a MIB', `<p class="muted" style="margin:0 0 8px;max-width:700px">Numbers defined by the MIB files you have loaded (Settings → SNMP → MIB files). Choose a MIB file, or search by name, module, file name or OID (several words must all match). A table column is added row by row (every row its own value); <b>Whole table</b> adds all value columns of the table and uses its comment/name column to name the rows. Values that the device sends as text ("12.4") are read as numbers.</p><div class="toolbar" style="margin:0 0 8px"><select id="mbF" style="max-width:260px" title="Only this MIB file"><option value="">All MIB files</option></select><input type="search" id="mbQ" placeholder="for example temperature, battery, if-mib" style="width:260px"><span class="muted" id="mbN"></span><span class="spacer"></span><button id="mbPrev">‹ Previous</button><button id="mbNext">Next ›</button></div><div id="mbR" style="max-height:340px;overflow:auto"></div>`, true);
